# Type definitions for clarity
Point_G1 = Any  # G1 point
Point_G2 = Any  # G2 point
Scalar = int  # Field element
Polynomial = List[Scalar]  # List of coefficients: [a_0, a_1, ..., a_n]
SRS_G1 = List[Point_G1]  # Powers of tau in G1: [G1, G1*tau, G1*tau^2, ...]
SRS_G2 = List[Point_G2]  # Powers of tau in G2: [G2, G2*tau]



def evaluate_polynomial(poly: Polynomial, point: Scalar) -> Scalar:
    """
    Evaluate a polynomial at a specific point using Horner's method.
    Args:
        poly: Polynomial coefficients [a_0, a_1, ..., a_n]
        point: Point to evaluate at

    Returns:
        Polynomial evaluation result
    """
    result = 0
    for coeff in reversed(poly):
        result = (result * point + coeff) % curve_order
    return result



def compute_polynomial_quotient(poly: Polynomial, value: Scalar, point: Scalar) -> Polynomial:
    """
    Compute the quotient polynomial q(X) = (f(X) - value) / (X - point)
    """
    # Initialize result and remainder
    n = len(poly)
    result = [0] * (n - 1)
    r = poly[n - 1]

    # Synthetic division
    for i in range(n - 2, -1, -1):
        result[i] = r
        r = (r * point + poly[i]) % curve_order

    # Check remainder - should be equal to value
    assert r == value, "Polynomial does not evaluate to the claimed value"

    return result



def commit_to_polynomial(polynomial: Polynomial,srs_g1: SRS_G1=0) -> Point_G1:
    """
    Create a commitment to a polynomial using the SRS.
    Args:
        poly: Polynomial coefficients [a_0, a_1, ..., a_n]
        srs_g1: G1 elements of the SRS

    Returns:
        Commitment as a G1 point
    """
    # poly=extract_poly_coeffs(polynomial)
    poly=polynomial
    max_degree=2048
    srs_g1=[
            (FQ(x_int), FQ(y_int), FQ(1))
            for (x_int, y_int) in G1_powers
            ]

    assert len(poly) <= len(srs_g1), "Polynomial degree exceeds SRS size"

    # Initialize result to point at infinity
    result = bls12_381.Z1

    # Multi-scalar multiplication: Σ a_i * (G1 * tau^i)
    for i, coeff in enumerate(poly):
        if coeff != 0:
            term = multiply(srs_g1[i], coeff)
            result = add(result, term)

    return result


def create_kzg_proof(poly: Polynomial, point: Scalar, srs_g1: SRS_G1=G1_powers) -> Tuple[Point_G1, Scalar]:
    """
    Create a KZG proof for a polynomial evaluation at a point.

    Args:
        poly: Polynomial coefficients
        point: Point to evaluate at
        srs_g1: G1 elements of the SRS

    Returns:
        Tuple of (proof_commitment, value)
    """
    # Calculate the value of the polynomial at the point
    value = evaluate_polynomial(poly, point)

    # Compute quotient polynomial q(X) = (f(X) - value) / (X - point)
    quotient_poly = compute_polynomial_quotient(poly, value, point)

    # Commit to the quotient polynomial
    proof_commitment = commit_to_polynomial(quotient_poly, srs_g1)

    return proof_commitment, value


def verify_kzg_proof(
        commitment: Point_G1,
        proof: Point_G1,
        point: Scalar,
        value: Scalar,
        srs_g1: SRS_G1=G1_powers,
        srs_g2: SRS_G2=G2_powers
) -> bool:
    """
    Verify a KZG proof.

    Args:
        commitment: Commitment to the polynomial
        proof: Proof of evaluation
        point: Evaluation point
        value: Claimed value of polynomial at point
        srs_g1: G1 elements of SRS
        srs_g2: G2 elements of SRS

    Returns:
        True if proof is valid, False otherwise
    """
    srs_g1 = [
        (FQ(x_int), FQ(y_int), FQ(1))
        for (x_int, y_int) in G1_powers
    ]
    srs_g2 = [
        (FQ2([x[0], x[1]]), FQ2([y[0], y[1]]), FQ2([1, 0]))
        for (x, y) in G2_powers
    ]


    # Compute right side: e(commitment - [value]G1, G2)
    g1_value = multiply(G1, value)  #G1->G
    commitment_minus_value = add(commitment, neg(g1_value))
    # Right pairing: e(commitment - [value]G1, G2)
    right_pairing = pairing(srs_g2[0], commitment_minus_value)

    # Left pairing: e(proof, [tau]G2 - [point]G2)

    # Compute left side: e(proof, [tau]G2 - [point]G2)
    g2_point = multiply(srs_g2[0], point) # G2->H.i
    shifted_g2 = add(srs_g2[1], neg(g2_point))  # srs_g2[1]->H.t

    left_pairing = pairing(shifted_g2, proof)
    # print('left pair',left_pairing)
    # print('right pairing',right_pairing)

    # Check if pairings match

    print("Left Pairing Res=", left_pairing)
    print("Right Pairing Res=", right_pairing)

    return left_pairing == right_pairing



def extract_poly_coeffs(poly_expr):
    S_PRIME=52435875175126190479447740508185965837690552500527637822603658699938581184513 # short wierstrass prime field
    x = symbols('x')
    poly = Poly(poly_expr, x)
    degree = poly.degree()
    coeffs = [poly.coeff_monomial(x ** i) for i in range(degree + 1)]
    for i in range(len(coeffs)):
        coeffs[i]=coeffs[i]%S_PRIME
    return coeffs


